public class GameManager : MonoBehaviour
{
    public static event Action<int> OnPuntosActualizados;

    public void AgregarPuntos(int valor)
    {
        OnPuntosActualizados?.Invoke(valor);
    }
}

public class ScoreUI : MonoBehaviour
{
    void OnEnable()  => GameManager.OnPuntosActualizados += RefrescarUI;
    void OnDisable() => GameManager.OnPuntosActualizados -= RefrescarUI;
    void RefrescarUI(int p) => Debug.Log("Score: " + p);
}

